import zlib,re
data=open('cda_certidao_divida_ativa.pdf','rb').read()
print(len(data))
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    s=m.group(1)
    try:
        d=zlib.decompress(s)
        print(d.decode('latin-1')[:4000])
    except Exception as e:
        print('raw:', s[:200])
")"}

